rules:
.panel {
  background: linear-gradient(180deg, rgba(8, 20, 60, 0.78), rgba(3, 6, 24, 0.78));
  border: 2px solid var(--c);
  box-shadow: 0 0 14px rgba(25, 230, 255, 0.55), inset 0 0 18px rgba(25, 230, 255, 0.18);
  clip-path: polygon(18px 0, calc(100% - 18px) 0, 100% 18px, 100% calc(100% - 18px), calc(100% - 18px) 100%, 18px 100%, 0 calc(100% - 18px), 0 18px);
  padding: 12px 22px;
}
